#include <stdio.h>

int main(void)
{
    FILE *f = fopen("label.txt", "w");
    if (f == NULL) {
        return 1;
    }
    fputs("old", f);
    fclose(f);
    f = fopen("label.txt", "w");
    if (f == NULL) {
        return 1;
    }
    fputs("N", f);
    fclose(f);
    f = fopen("label.txt", "r");
    if (f == NULL) {
        return 1;
    }
    int n = 0;
    while (fgetc(f) != EOF) {
        n++;
    }
    printf("%d\n", n);
    fclose(f);
    return 0;
}

#include <stdio.h>

int main(void)
{
    FILE *f = fopen("letters.txt", "w");
    if (f == NULL) {
        return 1;
    }
    fputs("A", f);
    fclose(f);
    f = fopen("letters.txt", "a");
    if (f == NULL) {
        return 1;
    }
    fputs("B", f);
    fseek(f, 0L, SEEK_SET);
    fputs("C", f);
    fclose(f);
    f = fopen("letters.txt", "r");
    if (f == NULL) {
        return 1;
    }
    int ch;
    while ((ch = fgetc(f)) != EOF) {
        putchar(ch);
    }
    putchar('\n');
    fclose(f);
    return 0;
}

#include <stdio.h>

int main(void)
{
    FILE *f = fopen("tag.txt", "w+");
    if (f == NULL) {
        return 1;
    }
    fputs("ABCDE", f);
    fseek(f, 0L, SEEK_SET);
    fputs("XY", f);
    fseek(f, 0L, SEEK_SET);
    char line[8];
    fgets(line, sizeof line, f);
    printf("%s\n", line);
    fclose(f);
    return 0;
}
